(result, args, expected) => {
  const [words] = args;
  if (typeof result !== "string") return "Return a string of letters.";
  if (expected === "") return result === "" ? true : "No alphabet can put these words in this order, so return \"\".";
  if (result === "") return `These words are sorted under at least one alphabet (for example "${expected}"), so don't return "".`;
  const letters = new Set(words.join(""));
  const rank = new Map();
  for (let i = 0; i < result.length; i++) {
    const ch = result[i];
    if (!letters.has(ch)) return `"${ch}" doesn't appear in any word, so it can't be in the order.`;
    if (rank.has(ch)) return `"${ch}" appears more than once in your order.`;
    rank.set(ch, i);
  }
  for (const ch of letters) if (!rank.has(ch)) return `Your order is missing the letter "${ch}".`;
  for (let i = 0; i + 1 < words.length; i++) {
    const a = words[i];
    const b = words[i + 1];
    let j = 0;
    while (j < a.length && j < b.length && a[j] === b[j]) j++;
    if (j < a.length && j < b.length) {
      if (rank.get(a[j]) > rank.get(b[j])) return `"${a}" comes before "${b}", so "${a[j]}" must come before "${b[j]}", but your order has it after.`;
    } else if (a.length > b.length) return `"${a}" can't come before its own prefix "${b}" in any alphabet.`;
  }
  return true;
}
